(sh) => {
    sh.uniforms.uTime = U.uTime;
    sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\nattribute float aSeed;\nuniform float uTime;')
      .replace('#include <begin_vertex>', `#include <begin_vertex>\nfloat sk = aSeed * 6.2831; transformed.x += sin(uTime * 0.23 + sk) * ${drift}; transformed.z += cos(uTime * 0.19 + sk * 1.3) * ${drift}; transformed.y += mod(uTime * ${rise} * (0.6 + 0.8 * aSeed) + aSeed * 97.0, ${H});`);
  }

